BEGIN;
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

SELECT setval(pg_get_serial_sequence('ratings', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM ratings), 1), true);
SELECT setval(pg_get_serial_sequence('rating_images', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM rating_images), 1), true);

COMMIT;
